// Icônes SVG maison (aucune librairie externe).
// - Icônes « maquette » : tracés vectoriels extraits du PDF Figma, donc fidèles
//   au pixel. Remplissage en currentColor : elles prennent la couleur du texte.
// - Icônes « trait » (Search, List, Kanban) : dessinées à la main.
// aria-hidden + focusable=false : décoratives, c'est le texte voisin qui porte
// le sens pour les lecteurs d'écran.

type IconProps = { className?: string; size?: number };

/* ---------- Icônes de la maquette (pleines) ---------- */

function MockupIcon({
  viewBox,
  size = 16,
  className,
  children,
}: IconProps & { viewBox: string; children: React.ReactNode }) {
  return (
    <svg
      viewBox={viewBox}
      width={size}
      height={size}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      {children}
    </svg>
  );
}

